2026-04-19T01:08:03.371Z	13d093f2-1fbf-4606-b50a-01af4226653b	ERROR	{
  errorType: 'Error',
  errorMessage: 'Error: The "buffer" encoding is not supported',
  stackTrace: '    at _write (__cjs:/var/task/node_modules/lambda-stream/dist/ResponseStream.js:13:40)
    at writeOrBuffer (stream:3395:23)
    at _write (stream:3351:28)
    at <anonymous> (stream:3355:21)
    at <anonymous> (/var/task/index.js:4:18)
    at apply (__cjs:/var/task/node_modules/lambda-stream/dist/index.js:23:23)
',
