The likely cause is an incompatibility issue with the `ReadableStream` class created within `lambda-stream`. Naturally, the `ReadableStream` class created here does not anticipate receiving `buffer` as the encoding parameter.

```javascript
// node_modules/lambda-stream/dist/ResponseStream.js
const stream_1 = require("stream");
class ResponseStream extends stream_1.Stream.Writable {
    constructor() {
        super();
        this.response = [];
    }
    // @param chunk Chunk of data to unshift onto the read queue. For streams not operating in object mode, `chunk` must be a string, `Buffer`, `Uint8Array` or `null`. For object mode
    // streams, `chunk` may be any JavaScript value.
    _write(chunk, encoding, callback) {
        this.response.push(Buffer.from(chunk, encoding));
        callback();
    }
    // ...
}

