export const fixPadding = (base64Url: string): string => {
  const base64UrlWithoutPadding = removePadding(base64Url);

  return addPadding(base64UrlWithoutPadding);
};

export const addPadding = (base64Url: string): string => {
  const base64UrlWithoutPadding = removePadding(base64Url);
  const leftover = base64UrlWithoutPadding.length % 4;

  switch (leftover) {
    case 2:
      return base64UrlWithoutPadding + "==";
    case 3:
      return base64UrlWithoutPadding + "=";
    default:
      return base64Url;
  }
};

const fromUrl = (base64Url: string): string => {
