    await loadKeysIntoCache();
  }

  return cache[kid];
};

const cache: Record<string, CryptoKey> = {};
const encoder = new TextEncoder();

export const verifyJWT = async (bearerToken: string) => {
  const jwtToken = bearerToken.replace(/^Bearer /, "");
  const [headerBase64, payloadBase64, signatureBase64] = jwtToken.split(".");

  const out = {
    header: JSON.parse(decodeBase64Url(headerBase64)),
    payload: JSON.parse(decodeBase64Url(payloadBase64)),
    signature: decodeBase64Url(signatureBase64),
  };

  const key = await requestKey(out.header.kid);

  if (out.payload.iss !== expectedIssuer) {
    throw new JWTInvalidIssuerError(out.payload.iss, expectedIssuer);
  }

  const now = Math.floor(Date.now() / 1000);

  // if (out.payload.exp < now) {
  //   throw new JWTExpiredError(out.payload.exp, now);
  // }

  if (out.payload.aud !== COGNITO_CLIENT_ID) {
    throw new JWTInvalidAuditorError(out.payload.aud, COGNITO_CLIENT_ID);
  }

  const keyData = Uint8Array.from(
    decodeBase64Url(signatureBase64),
    (x) => x.charCodeAt(0),
  );
  const data = encoder.encode(`${headerBase64}.${payloadBase64}`);

  // https://dev.to/gyantocode/without-jwt-library-decode-and-verify-a-jwt-token-in-javascript-17mk
  const valid = await crypto.subtle.verify(
    key.algorithm.name,
    key,
    keyData,
    data,
  );

  if (!valid) {
    throw new JWTInvalidSignatureError();
  }

  return out.payload;
};

