Hi there! Not yet, top level is technically possible, but we have to do a significant engine update first so will take some time :)
In the meanwhile, you can use a special async init function like so:


```javascript
function sleep(ms: number) {
    return new Promise((resolve) => {
        setTimeout(resolve, ms);
    });
}


export const init = async () => {
    // do init here
   await sleep(100);
}


export const handle = async (event: APIGatewayProxyEvent): Promise<APIGatewayProxyResult> => {
    return response.success(200, { message: "hello world!" });
};
```

